function escapeHtml(value: string): string {
  return value.replace(/[&<>'"]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[character] ?? character);
}
export function clientFacingDocumentTitle(project: Project): string {
  const clientName = project.client.name.trim();
  const reportTitle = project.type === "client-report"
    ? "Technology Health Review"
    : project.type === "prospect-proposal" ? PROPOSAL_COVER_TITLE : project.presentation.title.trim() || "Technology Proposal";
  return clientName ? `${clientName} — ${reportTitle}` : reportTitle;
}
function preparedDate(project: Project): string {
  const source = project.presentation.publishedAt || project.updatedAt || project.createdAt;
  const value = new Date(source);
  if (Number.isNaN(value.getTime())) return "Prepared";
  return `Prepared ${new Intl.DateTimeFormat("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }).format(value)}`;
}

function pdfBrandIdentityHtml(): string {
  return `<span class="pdf-brand-identity"><img class="pdf-brand-logo" src="${ADVANTAGE_LOGO_DATA_URI}" alt="Advantage Technologies"></span>`;
}
function recommendationsHtml(project: Project): string { return project.recommendations.map((item, index) => `<article class="recommendation"><b>${String(index + 1).padStart(2, "0")}</b><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.clientValue)}</p></div></article>`).join(""); }
function painPoints(project: Project): string {
  const items = project.painPoints.filter(Boolean);
  return items.length ? `<section><span class="kicker">What matters most</span><div class="pain-grid">${items.slice(0, 6).map((item) => `<article>${escapeHtml(item)}</article>`).join("")}</div></section>` : "";
}

export function outstandingHipaaQuestionCount(project: Project): number {
  if (!project.hipaa.enabled) return 0;
  return HIPAA_QUESTIONS.filter((question) => question.ownership !== "advantage-prefill").filter((question) => {
    const answer = project.hipaa.answers.find((item) => item.questionId === question.id);
    return !answer || answer.response === "not-yet-assessed" || answer.deferred;
  }).length;
}

function hipaaScoreUpdateNotice(project: Project): string {
  const remaining = outstandingHipaaQuestionCount(project);
  // Return instructions belong only to PDFs that contain unanswered HIPAA fields.
  if (!remaining) return "This score reflects all responses currently provided and remains subject to Advantage Technologies’ review and verification.";
  return `Your current score is based on the information available today. Complete the ${remaining} unanswered question${remaining === 1 ? "" : "s"} included at the end of this document. Completing the missing information gives ${organizationReference(project)} a more accurate readiness review and may improve the displayed score. After the responses are reviewed, Advantage will update the assessment and provide a revised report and score. Please email this completed document to your Technology Consultant, or Patric.Beckman@adv-tech.com.`;
}

function hipaaResponseAppendixHtml(project: Project, pageClass: string, footerHtml = ""): string {
  if (!project.hipaa.enabled) return "";
  const score = scoreHipaaAssessment(project.hipaa);
  const outstanding = HIPAA_QUESTIONS.filter((question) => question.ownership !== "advantage-prefill").flatMap((question) => {
    const answer = project.hipaa.answers.find((item) => item.questionId === question.id);
    return !answer || answer.response === "not-yet-assessed" || answer.deferred ? [{ question, answer }] : [];
  });
  if (!outstanding.length) return "";
  const chunks: typeof outstanding[] = [];
  for (let index = 0; index < outstanding.length; index += 2) chunks.push(outstanding.slice(index, index + 2));
  return chunks.map((items, pageIndex) => {
    const isLastPage = pageIndex === chunks.length - 1;
    const completion = isLastPage ? `<div class="pdf-response-completion"><div class="pdf-response-completion-copy"><strong>Return the completed review</strong><span>Once the missing responses are reviewed, Advantage will update the assessment and send a revised report and score. Completing the missing information may improve the displayed score and will make the review more accurate.</span></div><div class="pdf-response-return-fields"><label><span>Completed by</span><div class="pdf-form-marker" data-pdf-field="hipaa.return.completedBy" data-pdf-field-type="text"></div></label><label><span>Title</span><div class="pdf-form-marker" data-pdf-field="hipaa.return.title" data-pdf-field-type="text"></div></label><label><span>Date</span><div class="pdf-form-marker" data-pdf-field="hipaa.return.date" data-pdf-field-type="text"></div></label><label class="wide"><span>Signature or typed name</span><div class="pdf-form-marker" data-pdf-field="hipaa.return.signature" data-pdf-field-type="text"></div></label></div><div class="pdf-response-email"><strong>Please email this completed document to your Technology Consultant, or Patric.Beckman@adv-tech.com.</strong><span>Please avoid including patient names, patient records, passwords, or other sensitive credentials in the notes.</span></div></div>` : "";
    return `<section class="${pageClass} pdf-response-page" data-pdf-page="true"><header class="pdf-response-heading"><span class="kicker">HIPAA follow-up · ${pageIndex + 1} of ${chunks.length}</span><h2>Information still needed</h2><p>Your current displayed readiness score is ${score.overall}%. Please answer what you can. It is okay to select Not sure when the information is not available.</p></header><div class="pdf-response-question-list">${items.map(({ question, answer }) => `<article class="pdf-response-question"><div class="pdf-response-question-heading"><span>${escapeHtml(question.id)}</span><em>${escapeHtml(question.category.replace(" Safeguards", ""))}</em></div><h3>${escapeHtml(question.title)}</h3><p>${escapeHtml(adaptOrganizationLanguage(question.question, project))}</p><small>${escapeHtml(adaptOrganizationLanguage(question.plainLanguageExplanation, project))}</small>${answer?.deferred ? `<b class="pdf-response-skipped">Skipped during the live review</b>` : ""}<div class="pdf-response-fields"><label><span>Response</span><div class="pdf-form-marker pdf-form-choice" data-pdf-field="hipaa.${escapeHtml(question.id)}.response" data-pdf-field-type="choice" data-pdf-options="Yes|No|Not sure|Not applicable" data-pdf-font-size="9"><i>Select Yes, No, Not sure, or Not applicable</i></div></label><label><span>Notes or helpful details</span><div class="pdf-form-marker pdf-form-notes" data-pdf-field="hipaa.${escapeHtml(question.id)}.notes" data-pdf-field-type="text" data-pdf-multiline="true" data-pdf-font-size="8"><i>Optional</i></div></label></div></article>`).join("")}</div>${completion}${footerHtml}</section>`;
  }).join("");
}

